#[cfg(feature="native-ocio")]
mod native {
use kimo_core::{color::{ocio_config::{Config,version},effect_domain::{DomainProcessor,WorkingDomain}},effects::{self,Frame,Params},keyframe::Prop};
use std::collections::BTreeMap;
const CONFIG:&str=include_str!("data/minimal_aces.ocio");
fn config()->Config{Config::from_text(CONFIG).unwrap()}
fn frame()->Frame{Frame{w:2,h:1,d:vec![-0.01,0.,0.0078125,0.5,0.18,1.,4.,1.]}}
#[test]fn parse_list_and_unknown_space(){let c=config();assert!(version().starts_with("2."));assert_eq!(c.colorspaces(),vec!["ACEScg","ACEScct","DisplayGamma2"]);let v=c.views();assert_eq!(v.len(),1);assert_eq!(v[0].display,"Test monitor");assert!(c.processor("wrong","ACEScg").is_err());assert!(c.processor("ACEScg","bad\0name").is_err());}
#[test]fn deterministic_processor_outlives_config(){let p=config().processor("ACEScg","ACEScct").unwrap();let mut first=frame();p.apply(&mut first).unwrap();for _ in 0..32{let mut f=frame();p.apply(&mut f).unwrap();assert_eq!(f.d,first.d);}}
// Independent published ACEScct Equation 1, not snapshots generated with OCIO.
// https://docs.acescentral.com/encodings/acescct/
#[test]fn published_acescct_values_and_roundtrip(){let c=config();let p=c.processor("ACEScg","ACEScct").unwrap();let inv=c.processor("ACEScct","ACEScg").unwrap();let mut f=frame();let original=f.d.clone();p.apply(&mut f).unwrap();for (i,(&input,&output)) in original.iter().zip(&f.d).enumerate(){if i%4==3{assert_eq!(input.to_bits(),output.to_bits());continue}let x=input as f64;let reference=if x<=0.0078125{10.5402377416545*x+0.0729055341958355}else{(x.log2()+9.72)/17.52};assert!((output as f64-reference).abs()<2e-6,"{input} -> {output}, expected {reference}");}inv.apply(&mut f).unwrap();for (&x,&y) in original.iter().zip(&f.d){assert!((x-y).abs()<1e-5,"{x} -> {y}");}}
#[test]fn identity_bit_exact_signed_hdr_zero_alpha(){let p=config().processor("ACEScg","ACEScg").unwrap();assert!(p.is_noop());let mut f=frame();f.d[1]=-0.;let bits:Vec<_>=f.d.iter().map(|x|x.to_bits()).collect();p.apply(&mut f).unwrap();assert_eq!(bits,f.d.iter().map(|x|x.to_bits()).collect::<Vec<_>>());}
#[test]fn hostile_configs_fail(){for s in ["", "garbage", "ocio_profile_version: 999", "\0", &"x".repeat(4*1024*1024+1)]{assert!(Config::from_text(s).is_err())}let file=CONFIG.replace("!<BuiltinTransform> {style: CURVE - ACEScct-LOG_to_LINEAR}","!<FileTransform> {src: /etc/passwd}");assert_ne!(file,CONFIG);assert!(Config::from_text(&file).err().unwrap().contains("FileTransform"));let nested=file.replace("!<FileTransform> {src: /etc/passwd}","!<GroupTransform> {children: [!<FileTransform> {src: /etc/passwd}]}");assert!(Config::from_text(&nested).is_err());}
#[test]fn input_rejection_transactional_and_recoverable(){let p=config().processor("ACEScg","ACEScct").unwrap();for d in [vec![0.;3],vec![f32::NAN,0.,0.,1.],vec![0.,0.,0.,-0.1]]{let mut f=Frame{w:1,h:1,d};let bits:Vec<_>=f.d.iter().map(|x|x.to_bits()).collect();assert!(p.apply(&mut f).is_err());assert_eq!(bits,f.d.iter().map(|x|x.to_bits()).collect::<Vec<_>>());}p.apply(&mut frame()).unwrap();}
#[test]fn display_domain_inserts_before_and_after(){let c=config();let p=DomainProcessor::new(&c,"ACEScg","ACEScg","DisplayGamma2",WorkingDomain::DisplayReferred).unwrap();let mut f=Frame{w:1,h:1,d:vec![0.25,0.25,0.25,0.4]};let mut params=Params::new();params.insert("stops".into(),Prop::new(1.));p.apply("exposure",&params,&BTreeMap::new(),&mut f,0.,0).unwrap();assert!((f.d[0]-1.).abs()<1e-6);assert_eq!(f.d[3],0.4);let p=DomainProcessor::new(&c,"DisplayGamma2","ACEScg","DisplayGamma2",WorkingDomain::SceneLinear).unwrap();p.apply("exposure",&params,&BTreeMap::new(),&mut f,0.,0).unwrap();assert!((f.d[0]-2f32.sqrt()).abs()<1e-6);}
#[test]fn effect_error_and_legacy_conflict_leave_frame_unchanged(){let p=DomainProcessor::new(&config(),"ACEScg","ACEScg","DisplayGamma2",WorkingDomain::DisplayReferred).unwrap();let mut f=frame();let original=f.d.clone();assert!(p.apply("unknown effect",&Params::new(),&BTreeMap::new(),&mut f,0.,0).is_err());assert_eq!(f.d,original);let mut s=BTreeMap::new();s.insert("wrapper_working_gamut".into(),"3".into());assert!(p.apply("exposure",&Params::new(),&s,&mut f,0.,0).is_err());assert_eq!(f.d,original);}
#[test]fn optional_official_aces2_config(){let Ok(path)=std::env::var("KIMO_TEST_NATIVE_ACES_CONFIG")else{return};let c=Config::from_file(path).unwrap();assert!(c.colorspaces().iter().any(|v|v=="ACEScg"));assert!(!c.views().is_empty());let p=c.processor("ACEScg","ACEScct").unwrap();let mut f=frame();p.apply(&mut f).unwrap();assert!((f.d[4]-0.4135884).abs()<2e-6);}
#[test]fn strings_effect_dispatch(){let path=concat!(env!("CARGO_MANIFEST_DIR"),"/tests/data/minimal_aces.ocio");let mut s=BTreeMap::new();for(k,v)in[("ocio_domain","display-referred"),("ocio_config",path),("ocio_working_space","ACEScg"),("ocio_linear_space","ACEScg"),("ocio_display_space","DisplayGamma2")]{s.insert(k.into(),v.into());}let mut f=Frame{w:1,h:1,d:vec![0.25,0.25,0.25,0.4]};let mut p=Params::new();p.insert("stops".into(),Prop::new(1.));effects::apply("exposure",&p,&s,&mut f,0.,0).unwrap();assert!((f.d[0]-1.).abs()<1e-6);s.insert("ocio_display_space".into(),"not found".into());let original=f.d.clone();assert!(effects::apply("exposure",&p,&s,&mut f,0.,0).is_err());assert_eq!(f.d,original);}
}
#[test]fn domain_parse_strict(){use kimo_core::color::effect_domain::WorkingDomain;assert!(WorkingDomain::parse("linearish").is_err());assert_eq!(WorkingDomain::parse("current").unwrap(),WorkingDomain::Current);}
#[cfg(not(feature="native-ocio"))]
#[test]fn unavailable_fails_closed(){let mut s=std::collections::BTreeMap::new();s.insert("ocio_domain".into(),"display-referred".into());let mut f=kimo_core::effects::Frame{w:1,h:1,d:vec![0.25,0.25,0.25,1.]};assert!(kimo_core::effects::apply("exposure",&kimo_core::effects::Params::new(),&s,&mut f,0.,0).err().unwrap().contains("native-ocio"));assert_eq!(f.d,vec![0.25,0.25,0.25,1.]);}
